      var ctx = canvas.getContext('2d');
      canvas.width = 200;
      canvas.height = 200;

      // 绘制白色背景
      ctx.fillStyle = '#ffffff';
      ctx.fillRect(0, 0, 200, 200);

      // 绘制黑色边框
      ctx.fillStyle = '#000000';
      ctx.fillRect(0, 0, 200, 200);
      ctx.fillStyle = '#ffffff';
      ctx.fillRect(2, 2, 196, 196);

      // 绘制简单的二维码图案
      ctx.fillStyle = '#000000';
      for (var i = 0; i < 25; i++) {
        for (var j = 0; j < 25; j++) {
          if ((i + j) % 3 === 0 || i * j % 5 === 0) {
            ctx.fillRect(i * 8, j * 8, 8, 8);
          }
        }
      }
